int count_x(const char* p, char x)
// ㅠ[]에 존재하는 ×와 동일한 값의 수를 센다.
// p= 0으로 끝나는 (의 배열을 가리킨다고 가정(그렇지 않으면 아무것도 가리키지 않음)
{
나 (p==nullptr)
return 0;
int count = 0;
while (*p) {
if (*p==x)
++count;
+p;
}
return count;

